import sys
sys.path.insert(0, ".")
from slow import count_primes
def orig(n):
    return sum(1 for k in range(2, n) if all(k % d for d in range(2, k)))
for n in list(range(-3, 400)) + [997, 1000, 1009]:
    r = count_primes(n)
    if r != orig(n) or type(r) is not int:
        sys.exit(1)
sys.exit(0 if count_primes(10007) == 1229 else 1)
